window.RP_SESSION={"id":"S-71f0ea942592","messages":[{"id":"RP-0089463","time":"2026-03-27T01:32:00+09:00","room":"RP","name":"캐너리","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"푼기윌라 마을에서 비싼 베사밀버섯을 한 주머니 보내 줬습니다. 이거면 길드원 모두가 향기롭고 따듯한 버섯 수프를 먹을 수 있겠어요.","characters":["P-ec8583137a09"]},{"id":"RP-0089464","time":"2026-03-27T01:33:00+09:00","room":"RP","name":"캐너리","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"캐너리는 소포를 받아서 내일 아침 식사에 쓰기 위해 식료품 저장고의 가장 공기가 잘 통하는 곳에 넣어두고.","characters":["P-ec8583137a09"]},{"id":"RP-0089465","time":"2026-03-27T01:33:00+09:00","room":"RP","name":"캐너리","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"야식을 찾는 길드원들을 위해 세 가지 정도의 야식을 준비하기로 한다.","characters":["P-ec8583137a09"]},{"id":"RP-0089466","time":"2026-03-27T01:39:00+09:00","room":"RP","name":"캐너리","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"코크드와 슈미트가 보내준 닭고기와 각종 채소들을 가지고 첫번째 요리를 시작한다. 아까 낮에 닭고기는 순살 정육으로 발라서 양파즙을 주재료로 한 소스에 담가뒀다, 뼈에 붙은 살과 자투리 고기, 가슴살 조금은 다져서 소금, 밀가루, 잘게 썬 각종 야채와 함께 볼로 만든다.","characters":["P-ec8583137a09"]},{"id":"RP-0089467","time":"2026-03-27T01:40:00+09:00","room":"RP","name":"캐너리","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그리고 버터를 두르고 그것들을 잘 구워낸 뒤, 그 자리에 감자와 난장이버섯을 얹어 기름을 빨아들이듯이 재차 굽는다.","characters":["P-ec8583137a09"]},{"id":"RP-0089468","time":"2026-03-27T01:41:00+09:00","room":"RP","name":"캐너리","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"닭고기의 마이야르가 팬에 남긴 맛 덩어리들을 약간의 수분을 더해 감자와 버섯으로 남김 없이 뽑아내면!","characters":["P-ec8583137a09"]},{"id":"RP-0089469","time":"2026-03-27T01:41:00+09:00","room":"RP","name":"캐너리","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"첫번째 야식. 닭 구이와 모듬 야채 구이 완성!","characters":["P-ec8583137a09"]},{"id":"RP-0089470","time":"2026-03-27T01:41:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":"헤일리가 등장합니다! 짜잔!","characters":["P-978c6ca18f92"]},{"id":"RP-0089471","time":"2026-03-27T01:42:00+09:00","room":"RP","name":"캐너리","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 헤일리 씨! 와서 야식 드시고 공부해요! \"","characters":["P-ec8583137a09"]},{"id":"RP-0089472","time":"2026-03-27T01:42:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"그래도 되려나요?\"\n\n 곧 잘 시간인데, 죄책감 드네요. 헤일리가 머쓱하게 웃는다.","characters":["P-978c6ca18f92"]},{"id":"RP-0089473","time":"2026-03-27T01:43:00+09:00","room":"RP","name":"캐너리","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 얼마든지요! 이 시간에 드시라고 만들어 놓은걸요. \"\n\n지난번에 도시에 갔을 때 엘타리온이 정체를 알 수 없는 빵데레 제빵사에게서 사 온 식빵을 썰자 식당과 주방 가득 고소한 향기가 퍼진다.","characters":["P-ec8583137a09"]},{"id":"RP-0089474","time":"2026-03-27T01:45:00+09:00","room":"RP","name":"캐너리","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 이건... 시간이 지나서 식긴 했어도 엄청 좋은 빵이네요. 큰 터치 없이 약간의 지방질과 단맛만 더해도 충분하겠어요. \"\n\n크호콜러넛을 으깨 만든 페이스트와, 직접 만든 무가당 땅콩버터를 조금씩 비율을 조정 해 가며 섞어, 식빵 위에 발라 헤일리에게 건낸다.\n\n\" 맛 봐요. 정말 맛있을거에요. \"","characters":["P-ec8583137a09"]},{"id":"RP-0089475","time":"2026-03-27T01:47:00+09:00","room":"RP","name":"헤일리","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"고마워요~.\"\n\n 헤일리가 식빵을 두 손으로 받아들고 한 입 베어문다.","characters":["P-978c6ca18f92"]},{"id":"RP-0089476","time":"2026-03-27T01:48:00+09:00","room":"RP","name":"캐너리","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"마지막으로, 이 모든 야식들을 하나로 묶어 줄, 상큼달콤한 음료수. 과일을 기반으로 약간의 향신료, 그리고 오랫동안 팍 끓지 않게 뭉근하게 알콜을 날린 정성이 들어간 뱅쇼까지.","characters":["P-ec8583137a09"]},{"id":"RP-0089477","time":"2026-03-27T01:49:00+09:00","room":"RP","name":"캐너리","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 천만에요. 헤일리 씨와 길드원 분들이 맛있게 먹는걸 보면 제가 기분이 다 좋은걸요. \"","characters":["P-ec8583137a09"]},{"id":"RP-0089478","time":"2026-03-27T01:49:00+09:00","room":"RP","name":"캐너리","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 우리 남편 밥 해주는것도 참 즐겁고... \"","characters":["P-ec8583137a09"]},{"id":"RP-0089479","time":"2026-03-27T01:49:00+09:00","room":"RP","name":"캐너리","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 아차차. \"","characters":["P-ec8583137a09"]},{"id":"RP-0089480","time":"2026-03-27T01:50:00+09:00","room":"RP","name":"캐너리","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 그, 러니까. 베레디르 군 밥 해 주는게 좋다는 뜻이에요. 다른 뜻은 아니고... \"","characters":["P-ec8583137a09"]},{"id":"RP-0089481","time":"2026-03-27T01:54:00+09:00","room":"RP","name":"캐너리","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 어쨌든 헤일리 씨. 그 빵 어때요? 품질 좋죠? \"","characters":["P-ec8583137a09"]},{"id":"RP-0089482","time":"2026-03-27T02:06:00+09:00","room":"RP","name":"캐너리","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"뱅쇼 한 모금","characters":["P-ec8583137a09"]},{"id":"RP-0089483","time":"2026-03-27T02:12:00+09:00","room":"RP","name":"캐너리","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-ec8583137a09"]},{"id":"RP-0089484","time":"2026-03-27T02:12:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
